  if item->>'kind'='team' then select id into strict team from public.teams where name=item->>'section_name';
  else select id into strict series from public.sticker_series where name=item->>'section_name'; end if;
  sid:=(item->>'id')::uuid;
  insert into public.stickers(id,collection_id,official_code,name,team_id,series_id,edition,variant,sticker_type,album_position,source_url,corroboration_url,verified_at,verified_by,published,catalog_section,catalog_order,catalog_review,catalog_number_status,catalog_notes,catalog_sources,verification_method)
  values(sid,c,item->>'code',item->>'name',team,series,item->>'edition',item->>'variant',case when item->>'name'='Escudo' then 'escudo' when series is not null then 'especial' else 'normal' end,null,item->'sources'->0->>'url',item->'sources'->1->>'url','2026-11-08'::timestamptz,actor,true,item->>'section',(item->>'order')::integer,'cross_checked',item->>'number_status',item->'notes',item->'sources','cross_checked_sources');
  insert into public.sticker_catalog_revisions(sticker_id,actor_id,new_data) select sid,actor,to_jsonb(s) from public.stickers s where id=sid;
 end loop;
 update public.collections set catalog_status='partial' where id=c;
 insert into public.audit_logs(actor_id,action,details) values(actor,'catalogue_cross_checked_publication',jsonb_build_object('published',654,'excluded_pending_review',7,'officially_complete',false,'method','cross_checked_sources','source_date','2026-11-08'));
end $seed$;
